/* Spatial scene/UI adapter. All positions and occupancy come from WorkshopSpatial. */
window.WorkshopSpaceView=(()=>{
  function layers(state,esc,status){const sp=WorkshopSpatial;
    const zones=state.space.zones.filter(z=>z.type!=='workstation').map(z=>`<button class="zone-beacon zone-${z.id}" data-zone="${z.id}" style="left:${z.position.x}px;top:${z.position.y}px" aria-label="Inspect ${esc(z.name)}"><span>${({lounge:'◡',briefing:'◇',library:'▥',operations:'⌘',archive:'▱'})[z.id]}</span><b>${esc(z.name)}</b><small>${z.occupancy.length} / ${z.seats.length}</small></button>`).join('');
    const actors=state.agents.filter(a=>a.lifecycle==='active').map(a=>{const l=state.space.locations[a.id];if(!l?.move&&l?.zoneId===sp.workId(a.id))return '';const p=sp.position(state,a.id),m=l.move,route=m?"path('"+m.points.map((p,i)=>(i?'L':'M')+p.x+' '+p.y).join(' ')+"')":'';
      const position=m?`left:0;top:0;offset-path:${route};offset-anchor:50% 100%;offset-rotate:0deg;animation:spatial-travel ${m.duration}ms linear both;animation-delay:-${Math.max(0,Date.now()-m.startedAt)}ms`:`left:${p.x}px;top:${p.y}px`;
      const label=(status(a.id)==='waiting'?'Approval needed · ':'')+(m?'Walking → '+sp.zone(state,m.toZoneId).name:l.activity==='lounging'?'Seated · lounge':sp.zone(state,l.zoneId)?.name);
      return `<button class="station spatial-agent ${m?'walking':l.activity==='lounging'?'seated':''} ${status(a.id)} ${a.id===state.selected?'selected':''}" data-spatial-agent="${a.id}" data-select-agent="${a.id}" data-agent-name="${esc(a.name)}" data-wire-x="${p.x}" data-wire-y="${p.y-70}" style="${position};${WorkshopIdentity.style(a)}" aria-pressed="${a.id===state.selected}" aria-label="Select ${esc(a.name)}, ${esc(label)}">${WorkshopIdentity.bot(a)}<b>${esc(a.name)}</b><small>${esc(label)}</small></button>`;
    }).join('');return `<div class="spatial-zones">${zones}</div><div class="spatial-actors">${actors}</div>`;
  }
  function controls(state,a,esc,busy){const sp=WorkshopSpatial,l=state.space.locations[a.id],selectedZone=sp.zone(state,state.ui.zone),z=(selectedZone&&(!selectedZone.agentId||selectedZone.agentId===a.id)?selectedZone:null)||sp.zone(state,l?.move?.toZoneId||l?.zoneId)||sp.zone(state,sp.workId(a.id)),disabled=a.lifecycle!=='active'||busy||!!l?.move;
    return `<section class="spatial-console" aria-label="Headquarters locations"><div class="location-heading"><div><span class="eyebrow">FLOOR CONTROL / ${esc(a.name)}</span><h3 role="status" aria-live="polite">${l?.move?'Walking to '+esc(sp.zone(state,l.move.toZoneId).name):a.lifecycle!=='active'?'Outside headquarters':esc(sp.zone(state,l.zoneId).name)}</h3><p>${l?.move?'Destination reserved. Queued tasks wait for arrival.':'Choose a location to inspect occupancy or move this operator.'}</p></div><label class="field">After completing work<select id="after-task"><option value="desk" ${state.space.afterTask[a.id]!=='lounge'?'selected':''}>Stay at workstation</option><option value="lounge" ${state.space.afterTask[a.id]==='lounge'?'selected':''}>Return to lounge</option></select></label></div><div class="zone-tabs" role="group" aria-label="Inspect a location">${state.space.zones.filter(z=>!z.agentId||z.agentId===a.id).map(x=>`<button data-zone="${x.id}" aria-pressed="${z.id===x.id}">${esc(x.type==='workstation'?'Own workstation':x.name)} <small>${x.occupancy.length}/${x.seats.length}</small></button>`).join('')}</div><div class="zone-detail"><div><h3>${esc(z.name)}</h3><p>${esc(z.activity)}</p><p>${z.occupancy.length?z.occupancy.map(o=>esc(state.agents.find(a=>a.id===o.agentId)?.name)+(o.arriving?' (arriving)':'')).join(' · '):'Unoccupied'}</p></div><div class="zone-actions"><button data-move-zone="${z.id}" ${disabled||l?.zoneId===z.id?'disabled':''}>Move ${esc(a.name)} here</button><button data-move-zone="${sp.workId(a.id)}" ${disabled||l?.zoneId===sp.workId(a.id)?'disabled':''}>Return to desk</button>${z.view?`<button data-view="${z.view}">Open ${esc(({laboratory:'handoff diagnostics',learn:'Field guide',queue:'Task operations',sessions:'Memory archive',blueprint:'Blueprint'})[z.view])} ↗</button>`:''}</div></div>${busy?'<p class="field-help">Finish or cancel the current task before relocation. Pausing keeps its workstation occupied.</p>':''}</section>`;
  }
  function schematic(state,esc,status){return `<section class="zone-schematic" aria-label="Shared spatial locations">${state.space.zones.filter(z=>z.occupancy.length&&z.type!=='workstation').map(z=>`<div><button data-zone="${z.id}">${esc(z.name)}</button>${z.occupancy.filter(o=>!o.arriving).map(o=>{const a=state.agents.find(a=>a.id===o.agentId),l=state.space.locations[a.id];return `<button class="station schematic-actor ${status(a.id)}" data-select-agent="${a.id}" style="${WorkshopIdentity.style(a)}">${WorkshopIdentity.bot(a)}<b>${esc(a.name)}</b><small>${l.move?'Walking → '+esc(WorkshopSpatial.zone(state,l.move.toZoneId).name):esc(l.activity)}</small></button>`;}).join('')}</div>`).join('')}</section>`;}
  return {layers,controls,schematic};
})();
